{"kind": "content", "icon": "🖼️", "head": "रंगों की योजना", "points": ["एक रंगी – एक रंग के शेड", "पूरक रंग योजना", "अनुरूप रंग योजना", "बहुरंगी चटक योजना", "अवसर के अनुसार चुनाव"], "say": "चित्र में रंगों के चुनाव को रंग योजना कहते हैं। एक रंगी योजना में एक ही रंग के हल्के-गहरे शेड लिए जाते हैं। पूरक योजना में आमने-सामने के रंग चुने जाते हैं। अनुरूप योजना में पास-पास के रंग। और बहुरंगी चटक योजना में बहुत से चमकीले रंग, जैसे हमारी लोक कलाओं में दिखते हैं। चित्र के विषय और भाव के अनुसार सही योजना चुनना कला की समझ का एक बड़ा हिस्सा है।"},
{"kind": "content", "icon": "⚖️", "head": "संतुलन और स्थान", "points": ["चित्र में भारीपन का बँटवारा", "सममित संतुलन – दोनों तरफ़ समान", "असममित संतुलन", "खाली जगह का महत्त्व", "केंद्र बिंदु"], "say": "संतुलन का अर्थ है चित्र में चीज़ों का ऐसा बँटवारा कि वह एक तरफ़ झुका न लगे। सममित संतुलन में बीच की रेखा के दोनों ओर एक जैसी आकृतियाँ होती हैं, जैसे तितली। असममित संतुलन में दोनों ओर अलग चीज़ें होती हैं, पर देखने में बराबर लगती हैं। चित्र में खाली जगह का भी महत्त्व है, वह आँखों को आराम देती है। हर चित्र का एक केंद्र बिंदु होता है, जिस पर नज़र सबसे पहले जाती है।", "img": "fa_butterfly.jpg", "cap": "तितली – सममित संतुलन · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "🔁", "head": "लय और दोहराव", "points": ["आकृतियों का दोहराव", "पैटर्न", "रंग या रेखा का क्रम", "रंगोली और अल्पना में", "संगीत जैसी लय चित्र में"], "say": "जब कोई आकृति, रंग या रेखा बार-बार निश्चित क्रम में दोहराई जाती है तो चित्र में लय बनती है, जैसे संगीत में ताल। इसे पैटर्न भी कहते हैं। साड़ी की किनारी, दीवार की बेल और रंगोली या अरिपन के डिज़ाइन इसके सुंदर उदाहरण हैं। लय चित्र में गति और व्यवस्था लाती है और देखने वाले की नज़र को चित्र के भीतर घुमाती रहती है।"},
{"kind": "content", "icon": "👁️", "head": "गहराई और परिप्रेक्ष्य", "points": ["पास की चीज़ बड़ी, दूर की छोटी", "रेखाएँ एक बिंदु पर मिलती हैं", "आगे की चीज़ें गहरी, पीछे हल्की", "सड़क या रेल की पटरी का उदाहरण", "तीन आयाम का भ्रम"], "say": "कागज़ सपाट होता है, पर कलाकार उस पर गहराई का भ्रम बनाते हैं, जिसे परिप्रेक्ष्य कहते हैं। इसमें पास की चीज़ें बड़ी और दूर की छोटी दिखाई जाती हैं। जैसे सीधी सड़क या रेल की पटरी पर खड़े होकर देखने पर वे दूर किसी बिंदु पर मिलती लगती हैं। आगे की चीज़ों में रंग गहरे और स्पष्ट, तथा पीछे की चीज़ों में हल्के और धुँधले होते हैं। मधुबनी जैसी लोक कलाओं में परिप्रेक्ष्य का प्रयोग नहीं होता, वहाँ सपाट चित्र ही सुंदर माने जाते हैं।", "img": "fa_perspective.jpg", "cap": "रास्ता – परिप्रेक्ष्य · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "💡", "head": "प्रकाश और छाया", "points": ["प्रकाश – जहाँ रोशनी पड़े", "छाया – जहाँ रोशनी न पहुँचे", "आकार में गोलाई का एहसास", "हल्का से गहरा – ग्रेडेशन", "शेडिंग – पेंसिल से"], "say": "जब किसी वस्तु पर रोशनी पड़ती है तो उसका एक हिस्सा चमकदार और दूसरा हिस्सा छाया वाला होता है। चित्र में प्रकाश और छाया दिखाने से वस्तु गोल और ठोस लगती है, जैसे गेंद या फल। पेंसिल से हल्के से गहरे की ओर धीरे-धीरे शेडिंग करके यह प्रभाव बनाया जाता है। इसे ग्रेडेशन कहते हैं। अभ्यास के लिए एक गोले को कमरे की खिड़की के पास रखकर उसकी छाया देखिए और बनाइए।", "img": "fa_shadow.jpg", "cap": "प्रकाश और छाया · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "🧪", "head": "प्रयोग – रंग चक्र बनाइए", "points": ["कागज़ पर बड़ा वृत्त बनाइए", "12 बराबर भागों में बाँटिए", "प्राथमिक रंग तीन स्थानों पर", "मिलाकर द्वितीयक रंग बनाइए", "बीच के स्थान तृतीयक से भरिए"], "say": "चलिए एक रंग चक्र बनाते हैं। कागज़ पर एक बड़ा वृत्त बनाकर उसे बारह बराबर भागों में बाँटिए। तीन जगह पर, बराबर दूरी पर, लाल, पीला और नीला भरिए। उनके बीच में उन्हें मिलाकर बनने वाले नारंगी, हरा और बैंगनी रंग भरिए। फिर बीच के छह भागों में तृतीयक रंग बनाइए। जब आप अपने हाथ से रंग मिलाएँगे तो रंगों के संबंध की सच्ची समझ आएगी, जो किताब पढ़ने से नहीं आती।"},
{"kind": "content", "icon": "🌿", "head": "प्रकृति से प्रेरणा", "points": ["पत्ते, फूल, पक्षी, आकाश", "सूर्योदय के रंग", "मोर और तितली", "अपने आसपास देखिए", "स्केचबुक में रोज़ एक चित्र"], "say": "कलाकारों की सबसे बड़ी शिक्षक प्रकृति है। पत्तों की रेखाएँ, फूलों के रंग, मोर के पंखों के आकार और सूर्योदय के रंग, सब कुछ सीखने का साधन है। अपने आसपास ध्यान से देखिए, गाँव, खेत, तालाब और पेड़ आपके सबसे अच्छे मॉडल हैं। एक स्केचबुक रखिए और रोज़ एक छोटा चित्र बनाइए। देखने की आदत ही सबसे अच्छा कलाकार बनाती है।", "img": "fa_sunrise.jpg", "cap": "प्रकृति की प्रेरणा · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "🖌️", "head": "पेंसिल, रंग और कागज़ का चुनाव", "points": ["पेंसिल – HB, 2B, 4B", "रंगीन पेंसिल, क्रेयॉन, स्केच पेन", "पोस्टर रंग, जल रंग", "मोटा ड्रॉइंग पेपर", "साफ़ ब्रश, पानी का कटोरा"], "say": "चित्र बनाने के लिए अलग-अलग माध्यम चुन सकते हैं। पेंसिल में एच बी सामान्य काम के लिए, और दो बी या चार बी गहरी शेडिंग के लिए ठीक रहती हैं। रंगों के लिए रंगीन पेंसिल, क्रेयॉन, स्केच पेन, पोस्टर रंग और जल रंग उपलब्ध हैं। जल रंग के लिए मोटा कागज़ चाहिए, वरना वह गल जाता है। ब्रश और पानी का कटोरा साथ रखिए, और काम के बाद ब्रश को धोकर सुखा लीजिए, तब वह लंबे समय तक चलता है।", "img": "fa_pencils.jpg", "cap": "चित्र बनाना · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "📌", "head": "सार", "points": ["कला के तत्व – रेखा, रंग, आकृति, बनावट, स्थान", "प्राथमिक रंग – लाल, पीला, नीला", "द्वितीयक रंग – नारंगी, हरा, बैंगनी", "गरम और ठंडे रंग, संतुलन, लय", "परिप्रेक्ष्य, प्रकाश और छाया"], "say": "सार यह है कि हर चित्र रेखा, रंग, आकृति, बनावट और स्थान जैसे तत्वों से बनता है। रेखा भाव दर्शाती है। लाल, पीला और नीला प्राथमिक रंग हैं और उनसे द्वितीयक और तृतीयक रंग बनते हैं। रंगों को गरम और ठंडे में बाँटा जाता है। संतुलन, लय, परिप्रेक्ष्य और प्रकाश-छाया चित्र को जीवंत बनाते हैं।"},
{"kind": "content", "icon": "📝", "head": "परीक्षा के लिए", "points": ["कला के तत्व गिनाइए", "रेखा के प्रकार और भाव", "प्राथमिक, द्वितीयक रंग", "रंग चक्र बनाना", "गरम-ठंडे रंगों के उदाहरण"], "say": "परीक्षा में कला के तत्वों के नाम और उनकी व्याख्या पूछी जाती है। रेखा के प्रकार और उनके भाव, प्राथमिक और द्वितीयक रंग, और रंग चक्र बनाना आना चाहिए। गरम और ठंडे रंगों के उदाहरण तथा पूरक रंग का अर्थ याद रखिए। प्रायोगिक परीक्षा में रंग चक्र बनाने या प्रकृति का दृश्य रंगने को कहा जा सकता है, इसलिए रंग मिलाना पहले से अभ्यास कीजिए।"},
{"kind": "content", "icon": "🎭", "head": "चित्र देखकर समझना", "points": ["पहले पूरा चित्र देखिए", "कौन सा रंग सबसे ज़्यादा है?", "रेखाएँ किस दिशा में हैं?", "चित्र कौन सा भाव देता है?", "अपनी राय, अपने शब्दों में"], "say": "कला का आनंद लेने के लिए चित्र को ध्यान से देखना भी सीखना होता है। पहले पूरा चित्र एक बार देखिए। फिर सोचिए कि सबसे ज़्यादा कौन सा रंग है, रेखाएँ किस दिशा में हैं, और चित्र आपको कौन सा भाव देता है, शांति, उत्साह या उदासी। इसके बाद अपनी राय अपने शब्दों में बताइए। कला में कोई एक सही उत्तर नहीं होता, पर कारण के साथ अपनी बात कहना ज़रूरी है। इस तरह आप कलाकार के मन को समझने लगते हैं।", "ext": 11},
